def count_consecutive_seats(seating, n, m, k):
    total_ways = 0

    # Check rows for k consecutive empty seats
    for row in seating:
        count = 0
        for seat in row:
            if seat == '.':
                count += 1
            else:
                count = 0

            if count >= k:
                total_ways += 1

    # Check columns for k consecutive empty seats
    for col in range(m):
        count = 0
        for row in range(n):
            if seating[row][col] == '.':
                count += 1
            else:
                count = 0

            if count >= k:
                total_ways += 1

    return total_ways

data = input().split()
